#include <bits/stdc++.h>
using namespace std; typedef unsigned long long u64;
u64 canon(array<int,6> r){sort(r.begin(),r.end());u64 k=0;for(int i=0;i<6;i++)k=k<<8|r[i];return k;}
array<int,6> dec(u64 k){array<int,6> r;for(int i=5;i>=0;i--){r[i]=k&255;k>>=8;}return r;}
int main(){
 vector<int> cols; for(int m=0;m<64;m++) if(__builtin_popcount(m)==3) cols.push_back(m);
 // orbits of width 7
 vector<u64> cur={0};
 for(int w=0;w<7;w++){vector<u64> nx; for(u64 k:cur){auto r=dec(k); for(int c:cols){array<int,6> s; for(int h=0;h<6;h++) s[h]=r[h]|(((c>>h)&1)<<w); nx.push_back(canon(s));}}
  sort(nx.begin(),nx.end()); nx.erase(unique(nx.begin(),nx.end()),nx.end()); cur=nx;}
 size_t N=cur.size(); fprintf(stderr,"orbits %zu\n",N);
 // orbit sizes
 vector<double> sz(N); for(size_t i=0;i<N;i++){auto r=dec(cur[i]); double s=720; int j=0; while(j<6){int k=j; while(k<6&&r[k]==r[j])k++; for(int t=2;t<=k-j;t++) s/=t; j=k;} sz[i]=s;}
 // transitions
 vector<uint32_t> T(N*20);
 for(size_t i=0;i<N;i++){auto r=dec(cur[i]); for(int ci=0;ci<20;ci++){int c=cols[ci]; array<int,6> s; for(int h=0;h<6;h++) s[h]=(r[h]|(((c>>h)&1)<<7))>>1; T[i*20+ci]=lower_bound(cur.begin(),cur.end(),canon(s))-cur.begin();}}
 // reads
 vector<string> ids; vector<int> ends; vector<array<double,256>> L,G,M;
 {ifstream f("reads.txt"); string id; int e; while(f>>id>>e){int a[8]; double p[8]; for(int k=0;k<8;k++) f>>a[k]>>p[k];
  array<double,256> l,g,m; for(int x=0;x<256;x++){double v=1; int mm=0; for(int k=0;k<8;k++){int b=(x>>k)&1; if(b==a[k]) v*=1-p[k]; else {v*=p[k];mm++;}} l[x]=v; g[x]=mm?0:v; m[x]=v*mm;}
  ids.push_back(id); ends.push_back(e); L.push_back(l); G.push_back(g); M.push_back(m);}}
 int R=ids.size(); vector<vector<int>> at(64); for(int i=0;i<R;i++) at[ends[i]].push_back(i);
 // factor at step e for orbit i, col ci: product over reads ending at e
 auto rows8=[&](size_t i,int ci,int*x){auto r=dec(cur[i]); int c=cols[ci]; for(int h=0;h<6;h++) x[h]=r[h]|(((c>>h)&1)<<7);};
 auto fr=[&](const array<double,256>&t,int*x){double s=0; for(int h=0;h<6;h++) s+=t[x[h]]; return s/6;};
 // backward: B[e] is per-member value for window ending at e (cols e-6..e), e=6..63
 vector<vector<double>> B(64); vector<double> lsB(64,0);
 B[63].assign(N,1.0);
 for(int e=63;e>=7;e--){vector<double> nb(N,0); int x[6];
  for(size_t i=0;i<N;i++){double s=0; for(int ci=0;ci<20;ci++){rows8(i,ci,x); double f=1; for(int r:at[e]) f*=fr(L[r],x); s+=f*B[e][T[i*20+ci]];} nb[i]=s/20;}
  double mx=*max_element(nb.begin(),nb.end()); for(auto&v:nb) v/=mx; lsB[e-1]=lsB[e]+log(mx); B[e-1]=move(nb);}
 // evidence: A initial = sz/20^7 summed with B[6]
 double Z=0; for(size_t i=0;i<N;i++) Z+=sz[i]*B[6][i]; Z/=pow(20.0,7);
 double logev=log(Z)+lsB[6];
 // forward with posteriors
 vector<double> A(N); for(size_t i=0;i<N;i++) A[i]=sz[i];
 vector<double> pe(R),ee(R);
 for(int e=7;e<=63;e++){vector<double> na(N,0); int x[6]; vector<double> num0(at[e].size(),0),num1(at[e].size(),0); double zz=0;
  for(size_t i=0;i<N;i++){ if(A[i]==0) continue; for(int ci=0;ci<20;ci++){rows8(i,ci,x); size_t j=T[i*20+ci];
    double f[4]; double ft=1; for(size_t q=0;q<at[e].size();q++){f[q]=fr(L[at[e][q]],x); ft*=f[q];}
    double w=A[i]*ft; na[j]+=w; double wb=w*B[e][j]; zz+=wb;
    for(size_t q=0;q<at[e].size();q++){ if(f[q]>0){double base=wb/f[q]; num0[q]+=base*fr(G[at[e][q]],x); num1[q]+=base*fr(M[at[e][q]],x);} } }}
  for(size_t q=0;q<at[e].size();q++){pe[at[e][q]]=num0[q]/zz; ee[at[e][q]]=num1[q]/zz;}
  double mx=*max_element(na.begin(),na.end()); for(auto&v:na) v/=mx; A=move(na);}
 FILE*o=fopen("/root/results/evidence.csv","w"); fprintf(o,"metric,value\nlog_evidence,%.12f\n",logev); fclose(o);
 o=fopen("/root/results/read_posteriors.csv","w"); fprintf(o,"read_id,p_error_free,expected_errors\n");
 for(int i=0;i<R;i++) fprintf(o,"%s,%.12f,%.12f\n",ids[i].c_str(),min(1.0,max(0.0,pe[i])),ee[i]); fclose(o);
 printf("logev %.10f\n",logev);
}
